tool_and_message_events.command:
/bin/bash -lc "node --input-type=module <<'NODE'
import { readFileSync, writeFileSync } from 'node:fs';
import { readMinor, mulDivMinor } from './work/lib/money.mjs';

const rows = JSON.parse(readFileSync('./work/rows.json', 'utf8'));
const settlement = rows.map(({ id, unitMinor, quantity }) => {
  if ("'!Number.isSafeInteger(quantity)) throw new Error(`Invalid quantity: ${id}`);
  // Division by one is exact for both signs, so the mode cannot affect net.
  const net = mulDivMinor(readMinor(unitMinor), BigInt(quantity), 1n, '"'floor');
  return {
    id,
    net: { unit: 'EUR-cent', value: net.toString() },
    fee: {
      status: 'blocked',
      authority: 'R-35',
      decisionOwner: 'Марина, владелец расчётов',
      requiredDecision: 'Утвердить формулу сбора для отдела B, включая числитель и знаменатель ставки и правило округления.',
    },
  };
});
writeFileSync('./settlement.json', JSON.stringify(settlement, null, 2) + '\\n', { flag: 'wx' });
NODE
node --input-type=module <<'NODE'
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { readMinor } from './work/lib/money.mjs';

const readJson = path => JSON.parse(readFileSync(path, 'utf8'));
const rows = readJson('./work/rows.json');
const settlement = readJson('./settlement.json');
assert.deepEqual(settlement.map(row => row.id), rows.map(row => row.id));
assert.deepEqual(settlement.map(row => row.net), [
  { unit: 'EUR-cent', value: '153' },
  { unit: 'EUR-cent', value: '-30' },
]);
assert.deepEqual(settlement.map(row => readMinor(row.net.value)), [153n, -30n]);
for (const { fee } of settlement) {
  assert.deepEqual(Object.keys(fee).sort(), ['authority', 'decisionOwner', 'requiredDecision', 'status']);
  assert.equal(fee.status, 'blocked');
  assert.equal(fee.authority, 'R-35');
  assert.match(fee.decisionOwner, /Марина/);
  assert.match(fee.requiredDecision, /числитель.*знаменатель.*округления/);
}
console.log('Verified: all row IDs, exact net DTOs, module round trip and fee decision status.');
NODE"

